// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const EMISSOR = 'Escola Exemplo de Idiomas';
const URL_VALIDACAO = 'https://exemplo.com/webhook/validar';  // endereço público deste fluxo
const LOGO_URL = '';        // opcional: logo no topo da página
const COR = '#0f3d3e';      // opcional: cor do cabeçalho e do botão
const COR_DESTAQUE = '';    // opcional: faixa fina sob o cabeçalho (ex.: a segunda cor da escola)
const LINKEDIN_ORGANIZATION_ID = '';  // opcional: ID numérico da página no LinkedIn
// ====================================================================

const TIPOS = {
  certificado_curso: 'Certificado de conclusão de curso',
  certificado_semestre: 'Certificado de conclusão de semestre',
  certificado_trimestre: 'Certificado de conclusão de trimestre',
  declaracao_matricula: 'Declaração de matrícula',
  declaracao_termino_semestre: 'Declaração de término de semestre',
};
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho',
  'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const esc = v => String(v ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const txt = v => String(v ?? '').trim();

function data(valor) {  // 'AAAA-MM-DD' ou 'DD/MM/AAAA' -> {dia, mes, ano}, ou null
  let m = txt(valor).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return { ano: +m[1], mes: +m[2], dia: +m[3] };
  m = txt(valor).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m) return { ano: +m[3], mes: +m[2], dia: +m[1] };
  return null;
}

const { estado, id } = $('Preparar (subfluxo)').first().json;
const entrada = $input.all().map(i => i.json);
let resultado = estado;
let doc = null;
let linkedin = '';

if (entrada.some(r => r.error)) {
  resultado = 'indisponivel';  // falha ao ler a planilha: detalhe só no n8n
} else if (estado === 'consultar') {
  // Nenhuma linha, ou o mesmo ID em mais de uma linha (ambíguo): não encontrado.
  const linhas = entrada.filter(r => txt(r.id) === id);
  if (linhas.length !== 1) {
    resultado = 'nao_encontrado';
  } else {
    const r = linhas[0];
    const tipo = txt(r.tipo_documento);
    const d = data(r.data_emissao);
    if (txt(r.status).toLowerCase() !== 'ativo' || !TIPOS[tipo]) {
      resultado = 'invalido';
      // Só o tipo e o nome parcial ("Maria S."), para quem confere saber que digitou o código certo.
      const partes = txt(r.nome).split(/\s+/);
      doc = { tipo: TIPOS[tipo] || '', nome: partes[0] + (partes.length > 1 ? ` ${partes[partes.length - 1][0]}.` : '') };
    } else {
      resultado = 'valido';
      // Só os campos públicos. Nunca CPF, RG, endereço ou outro dado do aluno.
      doc = {
        tipo: TIPOS[tipo],
        nome: txt(r.nome),
        curso: txt(r.curso),
        carga_horaria: txt(r.carga_horaria),
        data_emissao: d ? `${d.dia} de ${MESES[d.mes - 1]} de ${d.ano}` : '',
      };
      if (tipo.startsWith('certificado_') && d && URL_VALIDACAO) {
        const params = {
          startTask: 'CERTIFICATION_NAME',
          name: `${TIPOS[tipo]} — ${txt(r.curso)}`,
          ...(LINKEDIN_ORGANIZATION_ID ? { organizationId: LINKEDIN_ORGANIZATION_ID } : { organizationName: EMISSOR }),
          issueYear: d.ano,
          issueMonth: d.mes,
          certUrl: `${URL_VALIDACAO}?id=${id}`,
          certId: id,
        };
        linkedin = 'https://www.linkedin.com/profile/add?' + Object.entries(params)
          .map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
      }
    }
  }
}

// O HTML fica no subfluxo "Validar documento: página": há ambientes cujo firewall
// (WAF) barra o salvamento com código e página no mesmo fluxo. Aqui só os dados,
// já escapados.
const STATUS = { vazio: 200, valido: 200, invalido: 200, nao_encontrado: 404, limite: 429, indisponivel: 503 };
return [{ json: {
  status: STATUS[resultado], resultado, id: esc(id), emissor: esc(EMISSOR), logo_url: esc(LOGO_URL),
  cor: COR, botao: COR === '#0f3d3e' ? '#0e7c7b' : COR, destaque: COR_DESTAQUE,
  doc: doc && Object.fromEntries(Object.entries(doc).map(([k, v]) => [k, esc(v)])), linkedin: esc(linkedin),
} }];
